#!/usr/bin/env python3
"""Validate, approve, and render the project-local Markdown backlog.

Authored Markdown is the only durable backlog source. Files under
``backlog/_generated`` are deterministic projections and may be deleted.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import subprocess
import sys
import unicodedata
from datetime import datetime, timezone
from pathlib import Path, PurePosixPath

try:
    import vault_check
except ImportError:  # direct library use outside the packaged scripts dir
    vault_check = None


ID_RE = re.compile(r"^[A-Z][A-Z0-9]*-[0-9]{2,}$")
SLUG_RE = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
WIKILINK_RE = re.compile(r"^\[\[([^\[\]\n]+)\]\]$")
BA_ID_RE = re.compile(r"^(?P<space>[a-z0-9]+(?:-[a-z0-9]+)*):(?P<id>(?:AC|BR)-[A-Z]{2,4}-[0-9]{3,})$")
ANALYSIS_SCOPE_RE = re.compile(
    r"^(?P<space>[a-z0-9]+(?:-[a-z0-9]+)*)"
    r"(?:#(?P<domain>domains/[a-z0-9]+(?:-[a-z0-9]+)*"
    r"(?:/domains/[a-z0-9]+(?:-[a-z0-9]+)*)*))?$"
)
NAV_MARKER = "<!-- sec: nav -->"
GENERATED_MAP_MARKER = "<!-- generated by backlog_compile.py; do not edit by hand -->"
RELATION_START = "## Related knowledge <!-- sec: relations:generated:start -->"
RELATION_END = "<!-- sec: relations:generated:end -->"
APPROVAL_FIELDS = {"package_hash", "source_hash"}
POLICY_PATH = (Path(__file__).resolve().parent.parent / "skill-content"
               / "obsidian-vault" / "data" / "vault-policy.json")
WORK_KINDS = {"feature", "defect", "technical"}
SCENARIO_COVERAGE_CLASSES = (
    "empty", "boundary", "invalid-input", "authorization",
    "duplicate-concurrent", "failure", "adjacent-regression",
)
EVIDENCE_TYPES = {
    "issue-report", "decision", "acceptance-set", "rule-set", "landscape",
    "engagement", "api-contract", "data-model", "threat-model",
    "environment-reference",
}
REVIEW_PLACEHOLDERS = {
    "record the review result", "record the review result.", "tbd", "todo",
    "replace this placeholder", "replace this placeholder.", "none", "n/a",
}
REVIEW_PLACEHOLDER_RE = re.compile(
    r"^(?:(?:record|describe|document|add|write|enter|provide)\b.*"
    r"(?:\breview\b|\bresult\b|\bevidence\b|\bconclusion\b|\bhere\b).*|"
    r"(?:no|none)\s+(?:issues?|findings?|gaps?|concerns?)(?:\s+(?:found|identified))?|"
    r"looks good|all good|approved|pass(?:ed)?)\.?$",
    re.IGNORECASE,
)
GENERIC_REVIEW_RE = re.compile(
    r"^(?:(?:the )?complete package (?:has been )?reviewed carefully|"
    r"no blocking gap remains(?: after reviewing (?:the )?complete package)?|"
    r"no unresolved contradiction(?: remains)?|(?:this )?satisfies this lens|"
    r"looks good|all good|no findings)\.?$",
    re.IGNORECASE,
)
EPIC_GOAL_STUB = "Define the customer outcome and boundary."
STORY_STUBS = {
    "scope": "Describe the smallest valuable behavior.",
    "priority_reason": "Required for the epic outcome.",
    "User Value": "Describe the observable user or business value.",
    "Non-Goals": "List behavior deliberately excluded from this story.",
    "Acceptance": "- [ ] Map every cited criterion to an observable result.",
    "Delivery Notes": "Record delivery constraints without execution state.",
}
RESPONSIBILITY_STUB = (
    "- backend_developer: Own implementation and integration."
)
SCENARIO_STUBS = {
    "Given": "the preconditions are satisfied",
    "When": "the user performs the story action",
    "Then": "the expected outcome is observable",
}


class ApprovalFailure(RuntimeError):
    """Raised after an approval mutation cannot pass its closing check."""


def docs_root(value: str | None) -> Path:
    path = Path(value or ".").resolve()
    if path.name == "docs" and path.is_dir():
        return path
    return path / "docs" if (path / "docs").is_dir() else path


def project_config(docs: Path) -> dict:
    path = docs.parent / "config.json"
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return value if isinstance(value, dict) else {}


def designation_map(docs: Path) -> dict[str, str]:
    """Resolve display designations without making them machine identities."""
    try:
        policy = json.loads(POLICY_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        policy = {}
    configured_defaults = policy.get("default_designations", {})
    defaults = {
        key.replace("_", "-"): str(value).strip()
        for key, value in configured_defaults.items()
        if isinstance(value, str) and value.strip()
    } if isinstance(configured_defaults, dict) else {}
    configured = project_config(docs).get("doc_type_designations", {})
    if isinstance(configured, dict):
        defaults.update({
            str(key): str(value).strip()
            for key, value in configured.items()
            if isinstance(value, str) and value.strip()
        })
    return defaults


def typed_title(docs: Path, base: str, doc_type: str) -> str:
    base = base.strip()
    designation = designation_map(docs).get(
        doc_type, doc_type.replace("-", " ")
    ).strip()
    folded_base = unicodedata.normalize("NFKC", base).casefold()
    folded_designation = unicodedata.normalize("NFKC", designation).casefold()
    start = len(folded_base) - len(folded_designation)
    if (start >= 0 and folded_base.endswith(folded_designation)
            and (start == 0 or not (folded_base[start - 1].isalnum()
                                    or folded_base[start - 1] == "_"))):
        return base
    return f"{base} {designation}".strip()


def designation_title(docs: Path, doc_type: str) -> str:
    """Use the configured designation with output-language-aware casing."""
    value = designation_map(docs).get(
        doc_type, doc_type.replace("-", " ")
    ).strip()
    language = str(project_config(docs).get("output_language", ""))
    if language.casefold() in {"turkish", "türkçe", "turkce"}:
        initial = {"i": "İ", "ı": "I"}.get(value[:1], value[:1].upper())
    else:
        initial = value[:1].upper()
    return initial + value[1:]


def title_of(path: Path, fallback: str) -> str:
    if path.is_file():
        props, _ = parse_front_matter(path)
        title = props.get("title")
        if isinstance(title, str) and title.strip():
            return title.strip()
    return fallback


def project_origin(docs: Path) -> str:
    return str(project_config(docs).get("project_origin", "greenfield"))


def backlog_contract() -> dict:
    try:
        policy = json.loads(POLICY_PATH.read_text(encoding="utf-8"))
        contract = dict(policy["backlog_contract"])
        contract["_status_values"] = policy.get("status_values", {})
    except (OSError, KeyError, json.JSONDecodeError) as exc:
        raise RuntimeError(f"backlog policy is missing or invalid: {exc}") from exc
    required = {
        "story_owner_roles", "story_supporting_roles",
        "required_story_sections", "required_epic_review_sections",
        "required_backlog_review_sections", "experience_ref_types",
    }
    missing = sorted(required - set(contract))
    if missing:
        raise RuntimeError("backlog policy is missing: " + ", ".join(missing))
    return contract


def parse_scalar(value: str):
    value = value.strip()
    if not value:
        return ""
    if value.startswith("[") and value.endswith("]"):
        return [parse_scalar(item) for item in value[1:-1].split(",")
                if item.strip()]
    if value.lower() in {"true", "false"}:
        return value.lower() == "true"
    if value.isdigit():
        return int(value)
    return value.strip("\"'")


def parse_front_matter(path: Path) -> tuple[dict, str]:
    text = path.read_text(encoding="utf-8")
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return {}, text
    end = next((index for index, line in enumerate(lines[1:], 1)
                if line.strip() == "---"), -1)
    if end < 0:
        return {}, text
    result: dict = {}
    current = None
    for line in lines[1:end]:
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        if line.startswith("  - ") and current:
            result.setdefault(current, []).append(parse_scalar(line[4:]))
            continue
        if ":" not in line:
            continue
        key, value = line.split(":", 1)
        key = key.strip()
        if value.strip():
            result[key] = parse_scalar(value)
            current = None
        else:
            result[key] = []
            current = key
    return result, "\n".join(lines[end + 1:])


def front_matter(props: dict, body: str) -> str:
    lines = ["---"]
    for key, value in props.items():
        if isinstance(value, list):
            lines.append(f"{key}:")
            for item in value:
                rendered = (f'"{item}"' if isinstance(item, str)
                            and item.startswith("[[") else item)
                lines.append(f"  - {rendered}")
        elif value is not None:
            rendered = (f'"{value}"' if isinstance(value, str)
                        and value.startswith("[[") else value)
            lines.append(f"{key}: {rendered}")
    lines.extend(["---", body.lstrip("\n")])
    return "\n".join(lines).rstrip() + "\n"


def canonical(path: Path) -> bytes:
    props, body = parse_front_matter(path)
    relation_pattern = re.compile(
        r"\n*" + re.escape(RELATION_START) + r".*?"
        + re.escape(RELATION_END) + r"\n*",
        re.DOTALL,
    )
    body = relation_pattern.sub("\n\n", body).rstrip() + "\n"
    stable = {key: value for key, value in props.items()
              if key not in APPROVAL_FIELDS}
    payload = json.dumps(stable, sort_keys=True, ensure_ascii=False,
                         separators=(",", ":"))
    return (payload + "\n" + body.strip() + "\n").encode("utf-8")


def digest(path: Path) -> str:
    return "sha256:" + hashlib.sha256(canonical(path)).hexdigest()


def package_digest(docs: Path, paths: list[Path]) -> str:
    manifest = {
        path.relative_to(docs).as_posix(): digest(path)
        for path in sorted(paths)
    }
    data = json.dumps(manifest, sort_keys=True, ensure_ascii=False,
                      separators=(",", ":")).encode("utf-8")
    return "sha256:" + hashlib.sha256(data).hexdigest()


def note_id(props: dict, fallback: str) -> str:
    value = props.get("id")
    if isinstance(value, str) and value.strip():
        return value.strip()
    aliases = props.get("aliases", [])
    if isinstance(aliases, str):
        aliases = [aliases]
    for alias in aliases or []:
        if ID_RE.fullmatch(str(alias)):
            return str(alias)
    return fallback


def values(props: dict, key: str) -> list[str]:
    value = props.get(key, [])
    if isinstance(value, str):
        return [value] if value else []
    return [str(item) for item in value or []]


def split_wikilink(value: str) -> tuple[str, str, str] | None:
    match = WIKILINK_RE.fullmatch(value.strip())
    if not match:
        return None
    inner = match.group(1)
    alias = ""
    for separator in ("\\|", "|"):
        if separator in inner:
            inner, alias = inner.split(separator, 1)
            break
    target, _, anchor = inner.partition("#")
    return target.strip(), anchor.strip(), alias.strip()


def valid_target(target: str) -> bool:
    if (not target or target.startswith("/") or target.endswith(".md")
            or "\\" in target):
        return False
    return all(part not in {"", ".", ".."} for part in target.split("/"))


def read_link(docs: Path, value: str, label: str,
              errors: list[str]) -> tuple[str, str, str] | None:
    parsed = split_wikilink(value)
    if parsed is None:
        errors.append(f"{label} must be a quoted vault-absolute wikilink: {value}")
        return None
    target, anchor, alias = parsed
    if not valid_target(target):
        errors.append(f"{label} has invalid vault target: {target or value}")
        return None
    if not alias:
        errors.append(f"{label} must have a display alias: {value}")
    if anchor and not anchor.startswith("^"):
        errors.append(f"{label} may use only a stable block anchor: {value}")
    target_path = docs / f"{target}.md"
    if not target_path.is_file():
        errors.append(f"{label} targets missing note: {target}")
        return None
    if anchor:
        body = target_path.read_text(encoding="utf-8")
        if not re.search(rf"(?:^|\s)\^{re.escape(anchor[1:])}(?:\s|$)", body,
                         flags=re.MULTILINE):
            errors.append(f"{label} targets missing block #{anchor}: {target}")
    return target, anchor, alias


def note_status_and_type(path: Path) -> tuple[str, str]:
    props, _ = parse_front_matter(path)
    type_name = str(props.get("type", "")).strip().replace("_", "-")
    return str(props.get("status", "")), type_name


def validate_criterion_ref(docs: Path, value: str, label: str,
                           errors: list[str]) -> tuple[str, str, str] | None:
    parsed = read_link(docs, value, label, errors)
    if parsed is None:
        return None
    target, _anchor, alias = parsed
    identity = BA_ID_RE.fullmatch(alias)
    if identity is None:
        errors.append(f"{label} alias must be <space>:<AC-or-BR-id>: {alias}")
        return parsed
    space = identity.group("space")
    criterion_id = identity.group("id")
    prefix = f"business-analysis/{space}/"
    if not target.startswith(prefix):
        errors.append(f"{label} target does not belong to BA space {space}: {target}")
        return parsed
    registry_path = docs / "business-analysis" / space / "_generated" / "registry.json"
    try:
        registry = json.loads(registry_path.read_text(encoding="utf-8"))
        entry = (registry.get("ids") or {}).get(criterion_id)
    except (OSError, json.JSONDecodeError):
        entry = None
    if not isinstance(entry, dict):
        errors.append(f"{label} criterion is absent from approved BA registry: {alias}")
        return parsed
    expected = prefix + str(entry.get("doc", ""))
    if expected.removesuffix(".md") != target:
        errors.append(f"{label} criterion {alias} belongs to {expected}, not {target}")
    if entry.get("doc_status") != "approved":
        errors.append(f"{label} criterion owner is not approved: {alias}")
    status, type_name = note_status_and_type(docs / f"{target}.md")
    if status != "approved" or type_name not in {"acceptance-set", "rule-set"}:
        errors.append(f"{label} must target an approved acceptance-set or rule-set: {target}")
    return parsed


def validate_upstream_ref(docs: Path, value: str, label: str,
                          roots: tuple[str, ...], allowed_types: set[str],
                          errors: list[str]) -> tuple[str, str, str] | None:
    parsed = read_link(docs, value, label, errors)
    if parsed is None:
        return None
    target, _anchor, _alias = parsed
    if not target.startswith(roots):
        errors.append(f"{label} targets the wrong vault subtree: {target}")
        return parsed
    status, type_name = note_status_and_type(docs / f"{target}.md")
    if status != "approved":
        errors.append(f"{label} target is not approved: {target}")
    if allowed_types and type_name not in allowed_types:
        errors.append(f"{label} targets unsupported type {type_name}: {target}")
    return parsed


def headings(body: str) -> set[str]:
    return {match.group(1).strip() for match in
            re.finditer(r"^##\s+(.+?)\s*$", body, flags=re.MULTILINE)}


def section(body: str, title: str) -> str:
    match = re.search(rf"^##\s+{re.escape(title)}\s*$", body,
                      flags=re.MULTILINE)
    if not match:
        return ""
    following = re.search(r"^##\s+", body[match.end():], flags=re.MULTILINE)
    end = match.end() + following.start() if following else len(body)
    return body[match.end():end].strip()


def required_section_findings(body: str, required: list[str], path: str) -> list[str]:
    present = headings(body)
    errors = [f"{path} is missing required section: {title}"
              for title in required if title not in present]
    for title in required:
        if title in present and not section(body, title):
            errors.append(f"{path} required section is empty: {title}")
    return errors


def meaningful_text(value: str) -> bool:
    normalized = re.sub(r"\s+", " ", value).strip().casefold()
    if (not normalized or normalized in REVIEW_PLACEHOLDERS
            or re.search(r"<!--\s*todo\b|\b(?:todo|tbd)\s*:", normalized)):
        return False
    words = re.findall(r"[^\W_]+", normalized, flags=re.UNICODE)
    return (REVIEW_PLACEHOLDER_RE.fullmatch(normalized) is None
            and len(words) >= 5)


def normalized_text(value: object) -> str:
    return re.sub(r"\s+", " ", str(value)).strip().casefold()


def generic_review_text(value: str) -> bool:
    """Reject a generic verdict, not a concrete sentence containing one."""
    normalized = re.sub(r"\s+", " ", value).strip()
    normalized = re.sub(r"\[\[[^\[\]\n]+\]\]", "", normalized).strip()
    normalized = re.sub(
        r"^(?:says|states|records(?: that)?)\s+", "", normalized,
        flags=re.IGNORECASE,
    )
    return GENERIC_REVIEW_RE.fullmatch(normalized) is not None


def review_section_findings(body: str, required: list[str], path: str,
                            docs: Path) -> list[str]:
    errors = required_section_findings(body, required, path)
    for title in required:
        content = section(body, title)
        if title == "Deferred Criteria":
            continue
        evidence = re.search(
            rf"(?m)^Evidence \[{re.escape(title)}\]:\s*(\S.+?)\s*$",
            content,
        )
        conclusion = re.search(
            rf"(?m)^Conclusion \[{re.escape(title)}\]:\s*(\S.+?)\s*$",
            content,
        )
        if (evidence is None or not meaningful_text(evidence.group(1))
                or generic_review_text(evidence.group(1))):
            errors.append(
                f"{path} review section needs section-specific "
                f"Evidence [{title}]"
            )
        else:
            links = re.findall(r"\[\[[^\[\]\n]+\]\]", evidence.group(1))
            if not links:
                errors.append(
                    f"{path} review Evidence must cite a vault note: {title}"
                )
            for value in links:
                read_link(docs, value, f"{path} {title} Evidence", errors)
        if (conclusion is None or not meaningful_text(conclusion.group(1))
                or generic_review_text(conclusion.group(1))):
            errors.append(
                f"{path} review section needs section-specific "
                f"Conclusion [{title}]"
            )
    return errors


def table_cells(line: str) -> list[str]:
    raw = line.strip()
    if not raw.startswith("|") or not raw.endswith("|"):
        return []
    cells: list[str] = []
    current: list[str] = []
    escaped = False
    for char in raw[1:-1]:
        if char == "|" and not escaped:
            cells.append("".join(current).strip())
            current = []
        else:
            current.append(char)
        escaped = char == "\\" and not escaped
        if char != "\\":
            escaped = False
    cells.append("".join(current).strip())
    return cells


def structured_table(content: str, headers: tuple[str, ...], path: str,
                     label: str) -> tuple[list[dict[str, str]], list[str]]:
    lines = [line for line in content.splitlines() if line.strip().startswith("|")]
    if len(lines) < 2:
        return [], [f"{path} {label} must be a Markdown table"]
    actual = tuple(cell.casefold().replace(" ", "_")
                   for cell in table_cells(lines[0]))
    if actual != headers:
        return [], [f"{path} {label} columns must be: {', '.join(headers)}"]
    separator = table_cells(lines[1])
    if len(separator) != len(headers) or any(
            re.fullmatch(r":?-{3,}:?", cell) is None for cell in separator):
        return [], [f"{path} {label} has an invalid table separator"]
    rows: list[dict[str, str]] = []
    errors: list[str] = []
    for number, line in enumerate(lines[2:], 1):
        cells = table_cells(line)
        if len(cells) != len(headers):
            errors.append(f"{path} {label} row {number} has {len(cells)} cells; expected {len(headers)}")
            continue
        rows.append(dict(zip(headers, cells)))
    return rows, errors


def criterion_key(value: str) -> str:
    parsed = split_wikilink(value)
    if parsed is None:
        return ""
    alias = parsed[2]
    return alias if BA_ID_RE.fullmatch(alias) else ""


def approved_ba_universe(docs: Path,
                         errors: list[str] | None = None) -> dict[str, dict]:
    universe: dict[str, dict] = {}
    root = docs / "business-analysis"
    for registry_path in sorted(root.glob("*/_generated/registry.json")):
        space = registry_path.parent.parent.name
        try:
            registry = json.loads(registry_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            if errors is not None:
                errors.append(
                    f"{registry_path.relative_to(docs).as_posix()} is unreadable: {exc}"
                )
            continue
        ids = registry.get("ids", {}) if isinstance(registry, dict) else {}
        if not isinstance(ids, dict):
            if errors is not None:
                errors.append(
                    f"{registry_path.relative_to(docs).as_posix()} ids must be an object"
                )
            continue
        for identifier, entry in ids.items():
            if not isinstance(entry, dict) or not re.fullmatch(
                    r"(?:AC|BR)-[A-Z]{2,4}-[0-9]{3,}", str(identifier)):
                continue
            inferred_kind = str(identifier).split("-", 1)[0]
            if entry.get("kind", inferred_kind) not in {"AC", "BR"}:
                continue
            if entry.get("doc_status") != "approved":
                continue
            if entry.get("row_status", "active") != "active":
                continue
            key = f"{space}:{identifier}"
            universe[key] = {"space": space, "id": str(identifier), **entry}
    return universe


def scoped_ba_universe(docs: Path, scopes: list[str]) -> tuple[dict[str, dict],
                                                               list[str]]:
    selected: dict[str, dict] = {}
    errors: list[str] = []
    all_criteria = approved_ba_universe(docs, errors)
    if len(scopes) != len(set(scopes)):
        errors.append("backlog/backlog.md has duplicate analysis_scopes")
    for value in scopes:
        match = ANALYSIS_SCOPE_RE.fullmatch(value)
        if match is None:
            errors.append(
                "backlog/backlog.md has invalid analysis_scope; expected "
                f"<space> or <space>#domains/<path>: {value}"
            )
            continue
        space = match.group("space")
        domain = match.group("domain")
        matches = {
            key: entry for key, entry in all_criteria.items()
            if entry.get("space") == space and (
                domain is None
                or str(entry.get("doc", "")).startswith(domain + "/")
            )
        }
        if not matches:
            errors.append(
                f"backlog/backlog.md analysis_scope selects no active approved "
                f"BA criteria: {value}"
            )
        selected.update(matches)
    return selected, errors


def deferred_criteria(docs: Path, body: str,
                      path: str) -> tuple[dict[str, dict], list[str]]:
    rows, errors = structured_table(
        section(body, "Deferred Criteria"),
        ("criterion_ref", "owner_role", "reason", "revisit_trigger"),
        path, "Deferred Criteria",
    )
    result: dict[str, dict] = {}
    for number, row in enumerate(rows, 1):
        value = row["criterion_ref"]
        parsed = validate_criterion_ref(
            docs, value, f"{path} deferred criterion row {number}", errors
        )
        key = parsed[2] if parsed is not None and BA_ID_RE.fullmatch(parsed[2]) else ""
        if key in result:
            errors.append(f"{path} repeats deferred criterion: {key}")
        owner = row["owner_role"]
        if owner != "product_owner":
            errors.append(
                f"{path} deferred criterion {key or number} owner_role "
                "must be product_owner"
            )
        if not meaningful_text(row["reason"]):
            errors.append(f"{path} deferred criterion {key or number} needs a concrete reason")
        if not meaningful_text(row["revisit_trigger"]):
            errors.append(f"{path} deferred criterion {key or number} needs a concrete revisit_trigger")
        if key:
            result[key] = row
    return result, errors


def status_findings(props: dict, type_name: str, path: str,
                    contract: dict) -> list[str]:
    allowed = set(contract["_status_values"].get(type_name.replace("-", "_"), []))
    status = str(props.get("status", ""))
    errors = []
    if status not in allowed:
        errors.append(f"{path} has invalid {type_name} status: {status or '(missing)'}")
    tags = values(props, "tags")
    status_tags = [tag for tag in tags if tag.startswith("status/")]
    if status_tags != [f"status/{status}"]:
        errors.append(f"{path} status tag does not mirror status: {status}")
    return errors


def scenario_blocks(body: str) -> list[tuple[str, str]]:
    matches = list(re.finditer(
        r"^##\s+([A-Z][A-Z0-9]*-[0-9]{2,}-TS-[0-9]{3})\s*$",
        body, flags=re.MULTILINE))
    result = []
    for index, match in enumerate(matches):
        end = matches[index + 1].start() if index + 1 < len(matches) else len(body)
        result.append((match.group(1), body[match.end():end]))
    return result


def scenario_fields(block: str) -> tuple[dict[str, str], list[str]]:
    fields: dict[str, str] = {}
    duplicates: list[str] = []
    active = ""
    for raw in block.splitlines():
        match = re.match(r"^-\s+([A-Za-z_]+):\s*(.*)$", raw)
        if match:
            key, value = match.group(1), match.group(2).strip()
            if key in fields:
                duplicates.append(key)
            fields[key] = value
            active = key
            continue
        nested = re.match(r"^\s{2,}-\s+(.+?)\s*$", raw)
        if nested and active == "source_refs":
            fields[active] = (fields[active] + ", " + nested.group(1)).strip(", ")
    return fields, duplicates


def source_ref_values(raw: str) -> tuple[list[str], bool]:
    matches = re.findall(r"\[\[[^\[\]\n]+\]\]", raw)
    residue = raw
    for value in matches:
        residue = residue.replace(value, "", 1)
    return matches, not residue.replace(",", "").strip()


def ref_identity(value: str) -> tuple[str, str, str] | None:
    return split_wikilink(value)


def scenario_findings(docs: Path, body: str, story_id: str,
                      criteria: list[str], evidence: list[str],
                      work_kind: str, path: str) -> tuple[list[str], list[str]]:
    errors: list[str] = []
    for candidate in re.findall(
        r"(?im)^##\s+(\S+-ts-\S+)\s*$", body
    ):
        if re.fullmatch(
                r"[A-Z][A-Z0-9]*-[0-9]{2,}-TS-[0-9]{3}", candidate
        ) is None:
            errors.append(
                f"{path} has malformed scenario-like heading: {candidate}"
            )
    blocks = scenario_blocks(body)
    ids = [item[0] for item in blocks]
    if not ids:
        return [f"{path} needs at least one scenario heading"], []
    if len(ids) != len(set(ids)):
        errors.append(f"{path} has duplicate scenario ids")
    criterion_set = {identity for value in criteria
                     if (identity := ref_identity(value)) is not None}
    evidence_set = {identity for value in evidence
                    if (identity := ref_identity(value)) is not None}
    covered: set[tuple[str, str, str]] = set()
    for scenario_id, block in blocks:
        if not scenario_id.startswith(f"{story_id}-TS-"):
            errors.append(f"{path} scenario {scenario_id} does not belong to {story_id}")
        fields, duplicates = scenario_fields(block)
        for duplicate in sorted(set(duplicates)):
            errors.append(f"{path} scenario {scenario_id} repeats {duplicate}")
        required_fields = [
            "category", "target", "automation", "source_refs",
            "Given", "When", "Then",
        ]
        for field in required_fields:
            if not fields.get(field, "").strip():
                errors.append(f"{path} scenario {scenario_id} is missing {field}")
        for field, sentinel in SCENARIO_STUBS.items():
            if normalized_text(fields.get(field, "")) == normalized_text(
                    sentinel):
                errors.append(
                    f"{path} scenario {scenario_id} has an untouched "
                    f"{field} stub"
                )
        automation = fields.get("automation", "").lower()
        if automation and automation not in {"required", "manual"}:
            errors.append(f"{path} scenario {scenario_id} has invalid automation value")
        if automation == "required" and not fields.get("automation_target", "").strip():
            errors.append(f"{path} scenario {scenario_id} is missing automation_target")
        target = fields.get("automation_target", "").strip()
        if target and (target.startswith("/") or ".." in Path(target).parts
                       or any(char.isspace() for char in target)):
            errors.append(f"{path} scenario {scenario_id} has invalid automation_target")
        source_values, clean = source_ref_values(fields.get("source_refs", ""))
        if fields.get("source_refs", "") and not clean:
            errors.append(f"{path} scenario {scenario_id} source_refs must contain only wikilinks")
        if len(source_values) != len(set(source_values)):
            errors.append(f"{path} scenario {scenario_id} repeats source_refs")
        for source in source_values:
            identity = ref_identity(source)
            label = f"{path} scenario {scenario_id} source_ref"
            if identity in criterion_set:
                validate_criterion_ref(docs, source, label, errors)
            elif identity in evidence_set and work_kind in {"defect", "technical"}:
                validate_evidence_ref(docs, source, label, errors)
            else:
                read_link(docs, source, label, errors)
                errors.append(
                    f"{path} scenario {scenario_id} cites planning source "
                    f"absent from its story: {source}"
                )
                continue
            if identity is not None:
                covered.add(identity)
    for source in (criteria if work_kind == "feature" else criteria + evidence):
        if ref_identity(source) not in covered:
            errors.append(f"{path} does not map planning source {source} to a scenario")
    errors.extend(scenario_coverage_findings(body, ids, path))
    return errors, ids


def scenario_coverage_findings(body: str, scenario_ids: list[str],
                               path: str) -> list[str]:
    rows, errors = structured_table(
        section(body, "Coverage Classes"),
        ("class", "disposition", "scenario_refs", "reason"),
        path, "Coverage Classes",
    )
    by_class: dict[str, dict[str, str]] = {}
    known_scenarios = set(scenario_ids)
    classified_scenarios: set[str] = set()
    for number, row in enumerate(rows, 1):
        class_name = row["class"]
        if class_name in by_class:
            errors.append(f"{path} repeats coverage class: {class_name}")
        by_class[class_name] = row
        if class_name not in SCENARIO_COVERAGE_CLASSES:
            errors.append(f"{path} has unknown coverage class: {class_name or number}")
        disposition = row["disposition"]
        if disposition not in {"covered", "not_applicable"}:
            errors.append(f"{path} coverage class {class_name or number} has invalid disposition: {disposition or '(missing)'}")
            continue
        raw_refs = row["scenario_refs"]
        refs = [] if raw_refs in {"", "-"} else [
            value.strip() for value in raw_refs.split(",") if value.strip()
        ]
        if len(refs) != len(set(refs)):
            errors.append(f"{path} coverage class {class_name or number} repeats scenario_refs")
        unknown = sorted(set(refs) - known_scenarios)
        if unknown:
            errors.append(f"{path} coverage class {class_name or number} cites unknown scenarios: {', '.join(unknown)}")
        if disposition == "covered" and not refs:
            errors.append(f"{path} covered class {class_name or number} needs scenario_refs")
        if disposition == "covered":
            classified_scenarios.update(set(refs) & known_scenarios)
        if disposition == "not_applicable":
            if refs:
                errors.append(f"{path} not_applicable class {class_name or number} must not cite scenarios")
            if not meaningful_text(row["reason"]):
                errors.append(f"{path} not_applicable class {class_name or number} needs a concrete reason")
    missing = sorted(set(SCENARIO_COVERAGE_CLASSES) - set(by_class))
    if missing:
        errors.append(f"{path} is missing coverage classes: {', '.join(missing)}")
    unclassified = sorted(known_scenarios - classified_scenarios)
    if unclassified:
        errors.append(
            f"{path} scenarios are not classified by Coverage Classes: "
            + ", ".join(unclassified)
        )
    return errors


def link_targets(docs: Path, props: dict, key: str, label: str,
                 errors: list[str]) -> list[str]:
    targets: list[str] = []
    for value in values(props, key):
        parsed = read_link(docs, value, label, errors)
        if parsed is not None:
            targets.append(parsed[0])
    return targets


def dependency_reason_targets(docs: Path, body: str, path: str,
                              errors: list[str]) -> set[str]:
    content = section(body, "Dependencies")
    found: set[str] = set()
    for line in content.splitlines():
        match = re.match(r"^-\s+(\[\[[^\[\]\n]+\]\])\s*(?::|-)\s*(\S.+?)\s*$", line)
        if not match:
            continue
        parsed = read_link(docs, match.group(1), f"{path} dependency reason", errors)
        if parsed is not None:
            found.add(parsed[0])
    return found


def validate_evidence_ref(docs: Path, value: str, label: str,
                          errors: list[str]) -> tuple[str, str, str] | None:
    parsed = read_link(docs, value, label, errors)
    if parsed is None:
        return None
    target = parsed[0]
    status, type_name = note_status_and_type(docs / f"{target}.md")
    if type_name not in EVIDENCE_TYPES:
        errors.append(
            f"{label} targets unsupported evidence type "
            f"{type_name or '(missing)'}: {target}"
        )
        return parsed
    allowed_statuses = ({"approved", "filed", "closed"}
                        if type_name == "issue-report" else
                        {"approved", "accepted"})
    if status not in allowed_statuses:
        errors.append(f"{label} target is not approved/accepted: {target}")
    return parsed


def evidence_findings(docs: Path, props: dict, path: str) -> list[str]:
    errors: list[str] = []
    refs = values(props, "related_to")
    if not refs:
        return [f"{path} defect/technical work needs related_to source, issue, or decision evidence"]
    if len(refs) != len(set(refs)):
        errors.append(f"{path} has duplicate related_to evidence")
    for value in refs:
        validate_evidence_ref(docs, value, f"{path} related_to evidence", errors)
    return errors


def has_cycle(graph: dict[str, set[str]]) -> bool:
    visiting: set[str] = set()
    visited: set[str] = set()

    def walk(node: str) -> bool:
        if node in visiting:
            return True
        if node in visited:
            return False
        visiting.add(node)
        if any(walk(target) for target in graph.get(node, set())):
            return True
        visiting.remove(node)
        visited.add(node)
        return False

    return any(walk(node) for node in graph)


def round_number(path: Path, props: dict, suffix: str, errors: list[str]) -> int:
    match = re.fullmatch(rf"round-([0-9]+)-{suffix}\.md", path.name)
    expected = int(match.group(1)) if match else 0
    actual = props.get("round")
    if not isinstance(actual, int) or actual != expected or expected < 1:
        errors.append(f"{path.as_posix()} round must match its filename")
    return expected


def collect(docs: Path) -> tuple[dict, list[str]]:
    contract = backlog_contract()
    root = docs / "backlog"
    errors: list[str] = []
    record = {"backlog": None, "backlog_reviews": [], "epics": [],
              "stories": [], "test_plans": [], "epic_reviews": []}
    root_note = root / "backlog.md"
    if not root_note.is_file():
        return record, ["backlog/backlog.md is missing"]
    props, root_body = parse_front_matter(root_note)
    if props.get("type") != "backlog":
        errors.append("backlog/backlog.md must have type: backlog")
    if props.get("owner_role") != "product_owner":
        errors.append("backlog/backlog.md owner_role must be product_owner")
    errors.extend(status_findings(props, "backlog", "backlog/backlog.md",
                                  contract))
    if "assignee" in props:
        errors.append("backlog/backlog.md must not contain assignee")
    record["backlog"] = {"path": root_note.relative_to(docs).as_posix(),
                         "id": note_id(props, "BACKLOG"), "props": props,
                         "body": root_body}

    rounds: set[int] = set()
    reviews_dir = root / "reviews"
    for path in sorted(reviews_dir.glob("round-*-backlog-review.md")):
        review_props, body = parse_front_matter(path)
        rel = path.relative_to(docs).as_posix()
        if review_props.get("type") != "backlog-review":
            errors.append(f"{rel} must have type: backlog-review")
        if review_props.get("owner_role") != "product_owner":
            errors.append(f"{rel} owner_role must be product_owner")
        errors.extend(status_findings(review_props, "backlog-review", rel,
                                      contract))
        if "assignee" in review_props:
            errors.append(f"{rel} must not contain assignee")
        review_round = round_number(path, review_props, "backlog-review", errors)
        if review_round in rounds:
            errors.append(f"backlog review round {review_round} is duplicated")
        rounds.add(review_round)
        errors.extend(review_section_findings(
            body, contract["required_backlog_review_sections"], rel, docs))
        record["backlog_reviews"].append({"path": rel, "props": review_props,
                                          "body": body,
                                          "id": note_id(review_props, path.stem),
                                          "round": review_round})

    epics_root = root / "epics"
    for epic_dir in sorted(epics_root.iterdir() if epics_root.is_dir() else []):
        if not epic_dir.is_dir() or epic_dir.name.startswith("_"):
            continue
        if not SLUG_RE.fullmatch(epic_dir.name):
            errors.append(f"invalid epic folder name: {epic_dir.name}")
            continue
        epic_path = epic_dir / "epic.md"
        if not epic_path.is_file():
            errors.append(f"{epic_path.relative_to(docs)} is missing")
            continue
        epic_props, epic_body = parse_front_matter(epic_path)
        epic_rel = epic_path.relative_to(docs).as_posix()
        epic_id = note_id(epic_props, epic_dir.name.upper())
        if not ID_RE.fullmatch(epic_id):
            errors.append(f"{epic_rel} has invalid id: {epic_id}")
        if epic_props.get("type") != "epic":
            errors.append(f"{epic_rel} must have type: epic")
        if epic_props.get("owner_role") != "product_owner":
            errors.append(f"{epic_rel} owner_role must be product_owner")
        errors.extend(status_findings(epic_props, "epic", epic_rel, contract))
        if not str(epic_props.get("goal", "")).strip():
            errors.append(f"{epic_rel} needs a goal")
        elif normalized_text(epic_props.get("goal")) == normalized_text(
                EPIC_GOAL_STUB):
            errors.append(f"{epic_rel} has an untouched goal stub")
        if "assignee" in epic_props:
            errors.append(f"{epic_rel} must not contain assignee")
        epic = {"path": epic_rel, "folder": epic_dir.name, "id": epic_id,
                "props": epic_props, "body": epic_body, "stories": [],
                "reviews": []}
        epic_rounds: set[int] = set()
        for review in sorted((epic_dir / "reviews").glob("round-*-epic-review.md")):
            review_props, review_body_text = parse_front_matter(review)
            review_rel = review.relative_to(docs).as_posix()
            if review_props.get("type") != "epic-review":
                errors.append(f"{review_rel} must have type: epic-review")
            if review_props.get("owner_role") != "product_owner":
                errors.append(f"{review_rel} owner_role must be product_owner")
            errors.extend(status_findings(review_props, "epic-review",
                                          review_rel, contract))
            if "assignee" in review_props:
                errors.append(f"{review_rel} must not contain assignee")
            review_round = round_number(review, review_props, "epic-review", errors)
            if review_round in epic_rounds:
                errors.append(f"{epic_id} review round {review_round} is duplicated")
            epic_rounds.add(review_round)
            errors.extend(review_section_findings(
                review_body_text, contract["required_epic_review_sections"],
                review_rel, docs))
            item = {"path": review_rel, "props": review_props,
                    "body": review_body_text,
                    "id": note_id(review_props, review.stem),
                    "round": review_round}
            epic["reviews"].append(item)
            record["epic_reviews"].append(item | {"epic_id": epic_id})

        stories_root = epic_dir / "stories"
        for story_dir in sorted(stories_root.iterdir() if stories_root.is_dir() else []):
            if not story_dir.is_dir() or story_dir.name.startswith("_"):
                continue
            if not SLUG_RE.fullmatch(story_dir.name):
                errors.append(f"invalid story folder name: {story_dir.name}")
                continue
            story_path = story_dir / "story.md"
            test_path = story_dir / "test-plan.md"
            if not story_path.is_file():
                errors.append(f"{story_path.relative_to(docs)} is missing")
                continue
            story_props, story_body = parse_front_matter(story_path)
            story_rel = story_path.relative_to(docs).as_posix()
            story_id = note_id(story_props, story_dir.name.upper())
            if not ID_RE.fullmatch(story_id):
                errors.append(f"{story_rel} has invalid id: {story_id}")
            if story_props.get("type") != "story":
                errors.append(f"{story_rel} must have type: story")
            errors.extend(status_findings(story_props, "story", story_rel,
                                          contract))
            if "assignee" in story_props:
                errors.append(f"{story_rel} must not contain assignee")
            for key in ("scope", "priority", "priority_reason", "owner_role"):
                if not str(story_props.get(key, "")).strip():
                    errors.append(f"{story_rel} needs {key}")
            errors.extend(required_section_findings(
                story_body, contract["required_story_sections"], story_rel))
            for key, sentinel in STORY_STUBS.items():
                actual = story_props.get(key, "") if key in {
                    "scope", "priority_reason"
                } else section(story_body, key)
                if normalized_text(actual) == normalized_text(sentinel):
                    errors.append(
                        f"{story_rel} has an untouched {key} stub"
                    )

            owner = str(story_props.get("owner_role", ""))
            owners = set(contract["story_owner_roles"])
            supporters = values(story_props, "supporting_roles")
            allowed_supporters = set(contract["story_supporting_roles"])
            if owner and owner not in owners:
                errors.append(f"{story_rel} has invalid owner_role: {owner}")
            if len(supporters) != len(set(supporters)):
                errors.append(f"{story_rel} has duplicate supporting_roles")
            if owner in supporters:
                errors.append(f"{story_rel} repeats owner_role in supporting_roles")
            for role in supporters:
                if role not in allowed_supporters:
                    errors.append(f"{story_rel} has invalid supporting_role: {role}")
            responsibilities = section(story_body, "Implementation Responsibilities")
            if normalized_text(RESPONSIBILITY_STUB) in normalized_text(
                    responsibilities):
                errors.append(
                    f"{story_rel} has an untouched implementation "
                    "responsibility stub"
                )
            for role in [owner] + supporters:
                if role and not re.search(rf"(?m)^-\s+{re.escape(role)}\s*:\s*\S", responsibilities):
                    errors.append(f"{story_rel} does not assign an implementation responsibility to {role}")

            criteria = values(story_props, "criterion_refs")
            experience = values(story_props, "experience_refs")
            evidence = values(story_props, "related_to")
            dependencies = values(story_props, "depends_on")
            design_refs = values(story_props, "uses_design")
            constraint_refs = values(story_props, "constrained_by")
            work_kind = str(story_props.get("work_kind", ""))
            if work_kind not in WORK_KINDS:
                errors.append(f"{story_rel} work_kind must be feature, defect, or technical")
            if project_origin(docs) != "existing" and work_kind != "feature":
                errors.append(f"{story_rel} greenfield work_kind must be feature")
            for key, refs in (("criterion_refs", criteria),
                              ("experience_refs", experience),
                              ("uses_design", design_refs),
                              ("constrained_by", constraint_refs),
                              ("depends_on", dependencies)):
                if len(refs) != len(set(refs)):
                    errors.append(f"{story_rel} has duplicate {key}")
            if work_kind == "feature" and not criteria:
                errors.append(f"{story_rel} needs criterion_refs")
            if work_kind == "feature" and not experience:
                errors.append(f"{story_rel} needs experience_refs")
            if work_kind == "feature" and not design_refs:
                errors.append(f"{story_rel} needs uses_design")
            if work_kind == "feature" and not any(
                    split_wikilink(value)
                    and split_wikilink(value)[0].startswith("solution-design/")
                    for value in constraint_refs):
                errors.append(
                    f"{story_rel} feature work needs a solution-design "
                    "constrained_by reference"
                )
            if work_kind in {"defect", "technical"}:
                errors.extend(evidence_findings(docs, story_props, story_rel))
            for value in criteria:
                validate_criterion_ref(docs, value, f"{story_rel} criterion_ref", errors)
            for value in experience:
                validate_upstream_ref(
                    docs, value, f"{story_rel} experience_ref",
                    ("experience-design/",), set(contract["experience_ref_types"]),
                    errors)
            for key, roots, types in (
                ("uses_design", ("design-system/",), {"design-master", "page-override"}),
                ("constrained_by", ("solution-design/", "system-architecture/"), set()),
            ):
                for value in values(story_props, key):
                    validate_upstream_ref(docs, value, f"{story_rel} {key}",
                                          roots, types, errors)

            derives = link_targets(docs, story_props, "derives_from",
                                   f"{story_rel} derives_from", errors)
            if derives != [epic_rel.removesuffix(".md")]:
                errors.append(f"{story_rel} must derive exactly from {epic_rel}")

            dependency_targets = link_targets(
                docs, story_props, "depends_on", f"{story_rel} depends_on", errors)
            reason_targets = dependency_reason_targets(
                docs, story_body, story_rel, errors)
            if set(dependency_targets) != reason_targets:
                missing = sorted(set(dependency_targets) - reason_targets)
                extra = sorted(reason_targets - set(dependency_targets))
                if missing:
                    errors.append(f"{story_rel} dependencies missing reasons: {', '.join(missing)}")
                if extra:
                    errors.append(f"{story_rel} dependency reasons are not declared: {', '.join(extra)}")

            test_props: dict = {}
            test_body = ""
            ids: list[str] = []
            if not test_path.is_file():
                errors.append(f"{test_path.relative_to(docs)} is missing")
            else:
                test_props, test_body = parse_front_matter(test_path)
                test_rel = test_path.relative_to(docs).as_posix()
                if test_props.get("type") != "test-plan":
                    errors.append(f"{test_rel} must have type: test-plan")
                errors.extend(status_findings(test_props, "test-plan", test_rel,
                                              contract))
                if test_props.get("owner_role") != "qa_engineer":
                    errors.append(f"{test_rel} owner_role must be qa_engineer")
                if "assignee" in test_props:
                    errors.append(f"{test_rel} must not contain assignee")
                expected_story_target = story_rel.removesuffix(".md")
                test_derives = link_targets(docs, test_props, "derives_from",
                                            f"{test_rel} derives_from", errors)
                test_verifies = link_targets(docs, test_props, "verifies",
                                             f"{test_rel} verifies", errors)
                if test_derives != [expected_story_target]:
                    errors.append(f"{test_rel} must derive exactly from {story_rel}")
                if test_verifies != [expected_story_target]:
                    errors.append(f"{test_rel} must verify exactly {story_rel}")
                scenario_errors, ids = scenario_findings(
                    docs, test_body, story_id, criteria, evidence,
                    work_kind, test_rel)
                errors.extend(scenario_errors)
            story = {
                "path": story_rel,
                "test_plan": test_path.relative_to(docs).as_posix(),
                "folder": story_dir.name, "id": story_id,
                "epic_id": epic_id, "props": story_props,
                "body": story_body, "test_props": test_props,
                "test_body": test_body, "scenario_ids": ids,
                "criteria": criteria, "experience_refs": experience,
                "work_kind": work_kind,
                "dependency_targets": dependency_targets,
            }
            epic["stories"].append(story)
            record["stories"].append(story)
            record["test_plans"].append({
                "path": story["test_plan"], "story_id": story_id,
                "props": test_props, "scenario_ids": ids,
            })
        if not epic["stories"]:
            errors.append(f"{epic_rel} has no stories")
        if not epic["reviews"]:
            errors.append(f"{epic_rel} has no epic review")
        record["epics"].append(epic)

    if not record["epics"]:
        errors.append("backlog/epics must contain at least one epic")
    if not record["backlog_reviews"]:
        errors.append("backlog/reviews must contain a cross-epic backlog review")
    epic_ids = [epic["id"] for epic in record["epics"]]
    story_ids = [story["id"] for story in record["stories"]]
    if len(epic_ids) != len(set(epic_ids)):
        errors.append("epic ids must be unique")
    if len(story_ids) != len(set(story_ids)):
        errors.append("story ids must be unique across epics")

    story_by_target = {story["path"].removesuffix(".md"): story
                       for story in record["stories"]}
    graph: dict[str, set[str]] = {}
    for story in record["stories"]:
        dependencies: set[str] = set()
        for target in story["dependency_targets"]:
            target_story = story_by_target.get(target)
            if target_story is None:
                errors.append(f"{story['id']} depends on unknown story target {target}")
                continue
            declared = next((value for value in values(story["props"], "depends_on")
                             if split_wikilink(value)
                             and split_wikilink(value)[0] == target), "")
            alias = split_wikilink(declared)[2] if declared else ""
            if alias != target_story["id"]:
                errors.append(f"{story['id']} dependency alias must be {target_story['id']}: {target}")
            dependencies.add(target_story["id"])
        graph[story["id"]] = dependencies
    if has_cycle(graph):
        errors.append("story dependency graph contains a cycle")

    errors.extend(review_coverage_findings(record, docs))
    errors.extend(global_criterion_coverage_findings(record, docs))
    errors.extend(existing_feature_package_findings(record, docs))
    return record, sorted(set(errors))


def latest(items: list[dict]) -> dict | None:
    return max(items, key=lambda item: item["round"]) if items else None


def dependency_edges(stories: list[dict], same_epic: bool | None,
                     record: dict) -> set[str]:
    by_target = {story["path"].removesuffix(".md"): story
                 for story in record["stories"]}
    edges = set()
    for story in stories:
        for target in story["dependency_targets"]:
            dependency = by_target.get(target)
            if dependency is None:
                continue
            is_same = dependency["epic_id"] == story["epic_id"]
            if same_epic is None or is_same == same_epic:
                edges.add(f"{story['id']} -> {dependency['id']}")
    return edges


def review_coverage_findings(record: dict, docs: Path) -> list[str]:
    errors: list[str] = []
    root_review = latest(record["backlog_reviews"])
    if root_review is not None:
        expected_parent = {record["backlog"]["path"].removesuffix(".md")}
        parent_targets = link_targets(
            docs, root_review["props"], "derives_from",
            f"{root_review['path']} derives_from", errors)
        actual_parent = set(parent_targets)
        if len(parent_targets) != len(actual_parent):
            errors.append(f"{root_review['path']} has duplicate derives_from links")
        if actual_parent != expected_parent:
            errors.append(f"{root_review['path']} must derive exactly from backlog/backlog.md")
        expected_epics = {epic["path"].removesuffix(".md")
                          for epic in record["epics"]}
        epic_targets = link_targets(
            docs, root_review["props"], "related_to",
            f"{root_review['path']} related_to", errors)
        actual_epics = set(epic_targets)
        if len(epic_targets) != len(actual_epics):
            errors.append(f"{root_review['path']} has duplicate related_to links")
        if actual_epics != expected_epics:
            errors.append(f"{root_review['path']} related_to set does not exactly cover every epic")
        expected_edges = dependency_edges(record["stories"], False, record)
        edge_values = values(root_review["props"], "dependency_refs")
        actual_edges = set(edge_values)
        if len(edge_values) != len(actual_edges):
            errors.append(f"{root_review['path']} has duplicate dependency_refs")
        if actual_edges != expected_edges:
            errors.append(f"{root_review['path']} dependency_refs do not exactly cover cross-epic dependencies")

    for epic in record["epics"]:
        review = latest(epic["reviews"])
        if review is None:
            continue
        expected_parent = {epic["path"].removesuffix(".md")}
        parent_targets = link_targets(
            docs, review["props"], "derives_from",
            f"{review['path']} derives_from", errors)
        actual_parent = set(parent_targets)
        if len(parent_targets) != len(actual_parent):
            errors.append(f"{review['path']} has duplicate derives_from links")
        if actual_parent != expected_parent:
            errors.append(f"{review['path']} must derive exactly from {epic['path']}")
        expected_targets = {
            target for story in epic["stories"]
            for target in (story["path"].removesuffix(".md"),
                           story["test_plan"].removesuffix(".md"))
        }
        verified_targets = link_targets(
            docs, review["props"], "verifies",
            f"{review['path']} verifies", errors)
        actual_targets = set(verified_targets)
        if len(verified_targets) != len(actual_targets):
            errors.append(f"{review['path']} has duplicate verifies links")
        if actual_targets != expected_targets:
            errors.append(f"{review['path']} verifies set does not exactly cover every story and test plan")
        expected_scenarios = {scenario for story in epic["stories"]
                              for scenario in story["scenario_ids"]}
        scenario_values = values(review["props"], "scenario_refs")
        actual_scenarios = set(scenario_values)
        if len(scenario_values) != len(actual_scenarios):
            errors.append(f"{review['path']} has duplicate scenario_refs")
        if actual_scenarios != expected_scenarios:
            errors.append(f"{review['path']} scenario_refs do not exactly cover every scenario")
        expected_edges = dependency_edges(epic["stories"], True, record)
        edge_values = values(review["props"], "dependency_refs")
        actual_edges = set(edge_values)
        if len(edge_values) != len(actual_edges):
            errors.append(f"{review['path']} has duplicate dependency_refs")
        if actual_edges != expected_edges:
            errors.append(f"{review['path']} dependency_refs do not exactly cover intra-epic dependencies")
    return errors


def global_criterion_coverage_findings(record: dict, docs: Path) -> list[str]:
    errors: list[str] = []
    covered = {
        key for story in record["stories"]
        for value in story["criteria"]
        if (key := criterion_key(value))
    }
    root_review = latest(record["backlog_reviews"])
    deferred: dict[str, dict] = {}
    if root_review is not None:
        deferred, findings = deferred_criteria(
            docs, root_review["body"], root_review["path"]
        )
        errors.extend(findings)
    scopes = values(record["backlog"]["props"], "analysis_scopes")
    if project_origin(docs) == "existing" and not scopes:
        universe = {key: {} for key in covered}
    elif project_origin(docs) == "existing":
        universe, scope_errors = scoped_ba_universe(docs, scopes)
        errors.extend(scope_errors)
    else:
        universe = approved_ba_universe(docs, errors)
    unknown_covered = sorted(covered - set(universe))
    if unknown_covered:
        errors.append("story criterion_refs contain values outside the approved BA universe: "
                      + ", ".join(unknown_covered))
    unknown_deferred = sorted(set(deferred) - set(universe))
    if unknown_deferred:
        errors.append("Deferred Criteria contains values outside the approved BA universe: "
                      + ", ".join(unknown_deferred))
    overlap = sorted(covered & set(deferred))
    if overlap:
        errors.append("criteria cannot be both story-covered and deferred: "
                      + ", ".join(overlap))
    uncovered = sorted(set(universe) - covered - set(deferred))
    if uncovered:
        errors.append("approved BA criteria/rules are neither story-covered nor deferred: "
                      + ", ".join(uncovered))
    return errors


def compiler_command_ok(command: list[str]) -> bool:
    try:
        return subprocess.run(
            command, capture_output=True, text=True, check=False, timeout=180
        ).returncode == 0
    except (OSError, subprocess.TimeoutExpired):
        return False


def existing_feature_package_findings(record: dict, docs: Path) -> list[str]:
    """Bind existing-project feature intake to approved compiler packages."""
    if project_origin(docs) != "existing":
        return []
    feature_stories = [
        story for story in record["stories"] if story["work_kind"] == "feature"
    ]
    if not feature_stories:
        return []
    errors: list[str] = []
    scopes = values(record["backlog"]["props"], "analysis_scopes")
    if not scopes:
        return [
            "existing feature backlog requires explicit analysis_scopes"
        ]
    script_dir = Path(__file__).resolve().parent
    spaces = {
        match.group("space") for value in scopes
        if (match := ANALYSIS_SCOPE_RE.fullmatch(value)) is not None
    }
    for space in sorted(spaces):
        if not compiler_command_ok([
            sys.executable, str(script_dir / "ba_compile.py"), "check",
            "--space", str(docs / "business-analysis" / space),
            "--vault-root", str(docs), "--gate", "approval", "--json",
        ]):
            errors.append(
                "existing feature backlog requires a compiler-valid approved "
                f"BA package for analysis scope {space}"
            )
    programs: set[str] = set()
    for story in feature_stories:
        for value in story["experience_refs"]:
            parsed = split_wikilink(value)
            parts = PurePosixPath(parsed[0]).parts if parsed is not None else ()
            if len(parts) >= 3 and parts[:2] == (
                    "experience-design", "programs"):
                programs.add(parts[2])
            else:
                errors.append(
                    f"{story['id']} experience_ref is not owned by an "
                    "Experience program package"
                )
    for program in sorted(programs):
        if not compiler_command_ok([
            sys.executable, str(script_dir / "experience_compile.py"),
            "check", "--root", str(docs / "experience-design"),
            "--program", program.upper(), "--gate", "--json",
        ]):
            errors.append(
                "existing feature backlog requires a compiler-valid approved "
                f"Experience package for program {program}"
            )
    solution = docs / "solution-design"
    landscape = solution / "landscape.md"
    engagement_paths = sorted((solution / "engagements").glob("*.md"))
    engagements_approved = bool(engagement_paths) and all(
        "Status: approved " in path.read_text(encoding="utf-8")
        for path in engagement_paths
    )
    if (not landscape.is_file() or note_status_and_type(landscape)[0] != "approved"
            or not engagements_approved or not compiler_command_ok([
                sys.executable, str(script_dir / "landscape_check.py"),
                "--tree", str(solution),
            ])):
        errors.append(
            "existing feature backlog requires a compiler-valid approved "
            "Solution Design package"
        )
    design = docs / "design-system"
    master = design / "MASTER.md"
    if (not master.is_file() or note_status_and_type(master)[0] != "approved"
            or not compiler_command_ok([
                sys.executable, str(script_dir / "design_system_compile.py"),
                "check", "--root", str(design),
            ])):
        errors.append(
            "existing feature backlog requires a compiler-valid approved "
            "Design System package"
        )
    return errors


def package_paths(record: dict, docs: Path) -> list[Path]:
    relatives = [record["backlog"]["path"]]
    relatives += [review["path"] for review in record["backlog_reviews"]]
    for epic in record["epics"]:
        relatives.append(epic["path"])
        relatives += [review["path"] for review in epic["reviews"]]
        for story in epic["stories"]:
            relatives.extend([story["path"], story["test_plan"]])
    return [docs / rel for rel in sorted(set(relatives))]


def approval_readiness_findings(record: dict) -> list[str]:
    errors: list[str] = []
    root_review = latest(record["backlog_reviews"])
    if root_review is None or root_review["props"].get("verdict") != "approved":
        errors.append("latest cross-epic backlog review verdict is not approved")
    elif root_review["props"].get("status") == "changes_requested":
        errors.append("latest cross-epic backlog review still requests changes")
    for epic in record["epics"]:
        review = latest(epic["reviews"])
        if review is None or review["props"].get("verdict") != "approved":
            errors.append(f"{epic['id']} latest epic review verdict is not approved")
        elif review["props"].get("status") == "changes_requested":
            errors.append(f"{epic['id']} latest epic review still requests changes")
        for story in epic["stories"]:
            if story["props"].get("status") != "planned":
                errors.append(f"{story['id']} must remain planned at backlog approval")
    return sorted(set(errors))


def approval_findings(record: dict, docs: Path) -> list[str]:
    errors: list[str] = []
    if record["backlog"]["props"].get("status") != "approved":
        errors.append("backlog status is not approved")
    root_review = latest(record["backlog_reviews"])
    if root_review is None or root_review["props"].get("status") != "approved":
        errors.append("latest cross-epic backlog review is not approved")
    for epic in record["epics"]:
        if epic["props"].get("status") != "approved":
            errors.append(f"{epic['id']} epic is not approved")
        review = latest(epic["reviews"])
        if review is None or review["props"].get("status") != "approved":
            errors.append(f"{epic['id']} latest epic review is not approved")
        for story in epic["stories"]:
            if story["props"].get("status") != "planned":
                errors.append(f"{story['id']} must remain planned at backlog approval")
            if story["test_props"].get("status") != "approved":
                errors.append(f"{story['id']} test plan is not approved")
    paths = package_paths(record, docs)
    timestamps: set[str] = set()
    for path in paths:
        props, _ = parse_front_matter(path)
        rel = path.relative_to(docs).as_posix()
        timestamp = props.get("approved_at_utc")
        if not isinstance(timestamp, str) or not timestamp:
            errors.append(f"{rel} approved_at_utc is missing")
        else:
            try:
                parsed = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                offset = parsed.utcoffset()
            except ValueError:
                offset = None
            if offset is None or offset.total_seconds() != 0:
                errors.append(f"{rel} approved_at_utc is not a UTC timestamp")
            timestamps.add(timestamp)
        expected = digest(path)
        if props.get("source_hash") != expected:
            errors.append(f"{rel} approved source_hash is stale")
    if len(timestamps) > 1:
        errors.append("approved package timestamps are not identical")
    expected_package = package_digest(docs, paths)
    if record["backlog"]["props"].get("package_hash") != expected_package:
        errors.append("backlog approved package_hash is stale")
    return sorted(set(errors))


def wikilink(path: str, title: str) -> str:
    return f"[[{path[:-3] if path.endswith('.md') else path}|{title}]]"


def append_nav(path: Path, nav_links: list[str]) -> None:
    text = path.read_text(encoding="utf-8")
    body = text.split(NAV_MARKER, 1)[0].rstrip()
    updated = body + "\n\n" + NAV_MARKER + "\n" + "\n".join(
        f"- {link}" for link in nav_links) + "\n"
    if updated != text:
        path.write_text(updated, encoding="utf-8")


def ensure_home_map(docs: Path) -> None:
    home = docs / "home.md"
    if not home.is_file():
        return
    text = home.read_text(encoding="utf-8")
    link = "[[maps/backlog|Backlog map]]"
    if not re.search(r"\[\[maps/backlog(?:\|[^\]\n]+)?\]\]", text):
        home.write_text(text.rstrip() + "\n\n- " + link + "\n", encoding="utf-8")


def normalize_backlog_map_aliases(path: Path, backlog_title: str) -> None:
    """Remove the legacy map alias that can steal the backlog title."""
    if not path.is_file():
        return
    props, body = parse_front_matter(path)
    aliases = values(props, "aliases")
    retained = [
        alias for alias in aliases
        if alias.casefold() not in {"backlog", backlog_title.casefold()}
    ]
    if retained:
        props["aliases"] = retained
    else:
        props.pop("aliases", None)
    body = re.sub(
        r"\[\[backlog/backlog(?:\|[^\]\n]+)?\]\]",
        f"[[backlog/backlog|{backlog_title}]]",
        body,
    )
    updated = front_matter(props, body)
    if updated != path.read_text(encoding="utf-8"):
        path.write_text(updated, encoding="utf-8")


def render_backlog_navigation(record: dict, docs: Path) -> None:
    ensure_home_map(docs)
    backlog_title = str(record["backlog"]["props"].get(
        "title", designation_title(docs, "backlog")
    ))
    map_path = docs / "maps" / "backlog.md"
    map_path.parent.mkdir(parents=True, exist_ok=True)
    if not map_path.is_file():
        map_path.write_text(front_matter(
            {"type": "moc", "title": "Backlog map", "tags": ["doc/moc"]},
            "# Backlog map\n"), encoding="utf-8")
    normalize_backlog_map_aliases(map_path, backlog_title)
    map_lines = [GENERATED_MAP_MARKER, "", "# Backlog index", "",
                 f"- {wikilink(record['backlog']['path'], backlog_title)}"]
    for review in record["backlog_reviews"]:
        map_lines.append(f"- {wikilink(review['path'], review['props'].get('title', review['id']))}")
    for epic in record["epics"]:
        map_lines.append(f"- {wikilink(epic['path'], epic['props'].get('title', epic['id']))}")
        for review in epic["reviews"]:
            map_lines.append(f"- {wikilink(review['path'], review['props'].get('title', review['id']))}")
        for story in epic["stories"]:
            map_lines.append(f"- {wikilink(story['path'], story['props'].get('title', story['id']))}")
            map_lines.append(f"- {wikilink(story['test_plan'], story['test_props'].get('title', story['id'] + ' test plan'))}")
    existing = map_path.read_text(encoding="utf-8")
    prefix = existing.split(GENERATED_MAP_MARKER, 1)[0].rstrip()
    map_path.write_text(prefix + "\n\n" + "\n".join(map_lines) + "\n",
                        encoding="utf-8")

    append_nav(docs / record["backlog"]["path"],
               ["[[maps/backlog|Backlog map]]"])
    for review in record["backlog_reviews"]:
        append_nav(docs / review["path"], [
            "[[maps/backlog|Backlog map]]",
            wikilink(record["backlog"]["path"], backlog_title),
        ])
    for epic in record["epics"]:
        epic_link = wikilink(epic["path"], epic["props"].get("title", epic["id"]))
        append_nav(docs / epic["path"], [
            "[[maps/backlog|Backlog map]]",
            wikilink(record["backlog"]["path"], backlog_title),
        ])
        for review in epic["reviews"]:
            append_nav(docs / review["path"],
                       ["[[maps/backlog|Backlog map]]", epic_link])
        for story in epic["stories"]:
            story_link = wikilink(story["path"],
                                  story["props"].get("title", story["id"]))
            append_nav(docs / story["path"], [
                "[[maps/backlog|Backlog map]]", epic_link,
                wikilink(story["test_plan"],
                         story["test_props"].get("title", "Test plan")),
            ])
            append_nav(docs / story["test_plan"],
                       ["[[maps/backlog|Backlog map]]", epic_link, story_link])


def render(record: dict, docs: Path) -> None:
    out = docs / "backlog" / "_generated"
    out.mkdir(parents=True, exist_ok=True)
    payload = {
        "schema_version": 2,
        "package_hash": record["backlog"]["props"].get("package_hash", ""),
        "backlog": {"id": record["backlog"]["id"],
                    "path": record["backlog"]["path"],
                    "status": record["backlog"]["props"].get("status")},
        "epics": [
            {"id": epic["id"], "path": epic["path"],
             "status": epic["props"].get("status"),
             "stories": [story["id"] for story in epic["stories"]]}
            for epic in record["epics"]
        ],
        "stories": [
            {"id": story["id"], "epic_id": story["epic_id"],
             "path": story["path"], "test_plan": story["test_plan"],
             "status": story["props"].get("status"),
             "work_kind": story["props"].get("work_kind"),
             "owner_role": story["props"].get("owner_role"),
             "supporting_roles": values(story["props"], "supporting_roles"),
             "scenario_ids": story["scenario_ids"],
             "criterion_refs": story["criteria"],
             "experience_refs": story["experience_refs"],
             "depends_on": values(story["props"], "depends_on")}
            for story in record["stories"]
        ],
        "reviews": {
            "cross_epic": [review["path"] for review in record["backlog_reviews"]],
            "epic": [review["path"] for review in record["epic_reviews"]],
        },
    }
    (out / "registry.json").write_text(
        json.dumps(payload, indent=2, ensure_ascii=False, sort_keys=True) + "\n",
        encoding="utf-8")
    board = [GENERATED_MAP_MARKER, "# Backlog board", "",
             "| Story | Epic | Status | Owner | Priority | Test plan |",
             "|---|---|---|---|---|---|"]
    for story in record["stories"]:
        board.append(
            f"| [[{story['path'][:-3]}|{story['id']}]] | {story['epic_id']} | "
            f"{story['props'].get('status', '')} | {story['props'].get('owner_role', '')} | "
            f"{story['props'].get('priority', '')} | "
            f"[[{story['test_plan'][:-3]}|scenarios]] |")
    (out / "board.md").write_text("\n".join(board) + "\n", encoding="utf-8")
    dependency = [GENERATED_MAP_MARKER, "# Dependency map", ""]
    for story in record["stories"]:
        dependencies = values(story["props"], "depends_on")
        dependency.append(f"- **{story['id']}** depends on "
                          + (", ".join(dependencies) if dependencies else "none"))
    (out / "dependency-map.md").write_text(
        "\n".join(dependency) + "\n", encoding="utf-8")
    coverage = [GENERATED_MAP_MARKER, "# Test coverage design", "",
                "| Story | Criteria | Scenarios | Automation required |",
                "|---|---:|---:|---:|"]
    for story in record["stories"]:
        required = sum(
            1 for _, block in scenario_blocks(story["test_body"])
            if scenario_fields(block)[0].get("automation", "").lower() == "required"
        )
        coverage.append(f"| {story['id']} | {len(story['criteria'])} | "
                        f"{len(story['scenario_ids'])} | {required} |")
    (out / "test-coverage.md").write_text(
        "\n".join(coverage) + "\n", encoding="utf-8")


def review_body(title: str, sections: list[str]) -> str:
    lines = [f"# {title}", ""]
    for name in sections:
        lines.append(f"## {name}")
        if name == "Deferred Criteria":
            lines.extend([
                "| criterion_ref | owner_role | reason | revisit_trigger |",
                "|---|---|---|---|",
            ])
        else:
            lines.extend([
                f"Evidence [{name}]: TODO: cite the exact reviewed vault note.",
                f"Conclusion [{name}]: TODO: record the section-specific conclusion.",
            ])
        lines.append("")
    return "\n".join(lines)


def coverage_class_table() -> str:
    lines = [
        "## Coverage Classes", "",
        "| class | disposition | scenario_refs | reason |",
        "|---|---|---|---|",
    ]
    for class_name in SCENARIO_COVERAGE_CLASSES:
        lines.append(
            f"| {class_name} | not_applicable | - | "
            "TODO: assess this coverage class. |"
        )
    return "\n".join(lines)


def init(args) -> int:
    docs = docs_root(args.docs)
    root = docs / "backlog"
    (root / "reviews").mkdir(parents=True, exist_ok=True)
    (root / "epics").mkdir(parents=True, exist_ok=True)
    if vault_check is not None and (docs / ".obsidian").is_dir():
        policy = vault_check.load_policy(vault_check.DEFAULT_POLICY)
        vault_check.reconcile_payload_fragment(docs, policy, "backlog")
    backlog_title = designation_title(docs, "backlog")
    review_title = designation_title(docs, "backlog-review")
    files = {
        root / "backlog.md": front_matter(
            {"type": "backlog", "title": backlog_title, "status": "draft",
             "owner_role": "product_owner", "revision": 1,
             "tags": ["doc/backlog", "status/draft"], "aliases": ["BACKLOG"]},
            f"# {backlog_title}\n\nThis file indexes the approved project scope.\n"),
        root / "reviews" / "round-1-backlog-review.md": front_matter(
            {"type": "backlog-review", "title": review_title,
             "status": "draft", "owner_role": "product_owner", "round": 1,
             "derives_from": [f"[[backlog/backlog|{backlog_title}]]"],
             "tags": ["doc/backlog-review", "status/draft"],
             "aliases": ["BACKLOG-REVIEW-001"]},
            review_body(review_title,
                        backlog_contract()["required_backlog_review_sections"])),
    }
    for path, text in files.items():
        if not path.exists():
            path.write_text(text, encoding="utf-8")
    map_path = docs / "maps" / "backlog.md"
    map_path.parent.mkdir(parents=True, exist_ok=True)
    if not map_path.is_file():
        map_path.write_text(front_matter(
            {"type": "moc", "title": "Backlog map", "tags": ["doc/moc"]},
            "# Backlog map\n"), encoding="utf-8")
    normalize_backlog_map_aliases(map_path, backlog_title)
    ensure_home_map(docs)
    append_nav(root / "backlog.md", ["[[maps/backlog|Backlog map]]"])
    append_nav(root / "reviews" / "round-1-backlog-review.md", [
        "[[maps/backlog|Backlog map]]",
        f"[[backlog/backlog|{backlog_title}]]",
    ])
    print(root)
    return 0


def status_tag(props: dict, status: str) -> None:
    tags = values(props, "tags")
    props["tags"] = [tag for tag in tags if not tag.startswith("status/")]
    props["tags"].append(f"status/{status}")
    props["status"] = status


def check(args) -> int:
    docs = docs_root(args.docs)
    try:
        record, errors = collect(docs)
    except RuntimeError as exc:
        record = {"epics": [], "stories": [], "test_plans": [],
                  "backlog_reviews": [], "epic_reviews": [], "backlog": None}
        errors = [str(exc)]
    if args.approved and record["backlog"]:
        errors.extend(approval_findings(record, docs))
    errors = sorted(set(errors))
    result = {
        "ok": not errors, "errors": errors,
        "counts": {"epics": len(record["epics"]),
                   "stories": len(record["stories"]),
                   "test_plans": len(record["test_plans"]),
                   "backlog_reviews": len(record["backlog_reviews"]),
                   "epic_reviews": len(record["epic_reviews"])},
    }
    if args.render and not errors:
        try:
            render(record, docs)
            render_backlog_navigation(record, docs)
            result["rendered"] = True
            if args.approved:
                record, closing_errors = collect(docs)
                closing_errors.extend(approval_findings(record, docs))
                errors.extend(closing_errors)
        except RuntimeError as exc:
            errors.append(f"render failed: {exc}")
        errors = sorted(set(errors))
        result["ok"] = not errors
        result["errors"] = errors
    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=False, sort_keys=True))
    else:
        for error in errors:
            print(f"ERROR [backlog] {error}")
        if not errors:
            print("backlog ok")
    return 1 if errors else 0


def snapshot_tree(root: Path) -> tuple[dict[Path, bytes], set[Path]]:
    files = {path: path.read_bytes() for path in root.rglob("*") if path.is_file()}
    dirs = {path for path in root.rglob("*") if path.is_dir()}
    dirs.add(root)
    return files, dirs


def restore_tree(root: Path, snapshot: tuple[dict[Path, bytes], set[Path]]) -> None:
    files, directories = snapshot
    for path in sorted((item for item in root.rglob("*") if item.is_file()),
                       reverse=True):
        if path not in files:
            path.unlink()
    for path, data in files.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    for path in sorted((item for item in root.rglob("*") if item.is_dir()),
                       key=lambda item: len(item.parts), reverse=True):
        if path not in directories:
            try:
                path.rmdir()
            except OSError:
                pass


def approve(args) -> int:
    docs = docs_root(args.docs)
    record, errors = collect(docs)
    errors.extend(approval_readiness_findings(record))
    errors = sorted(set(errors))
    if errors:
        print(json.dumps({"ok": False, "errors": errors}, indent=2,
                         ensure_ascii=False, sort_keys=True))
        return 1
    snapshot = snapshot_tree(docs)
    now = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
    try:
        transition_paths = [docs / record["backlog"]["path"]]
        transition_paths += [docs / epic["path"] for epic in record["epics"]]
        transition_paths += [docs / latest(record["backlog_reviews"])["path"]]
        transition_paths += [docs / latest(epic["reviews"])["path"]
                             for epic in record["epics"]]
        transition_paths += [docs / story["test_plan"]
                             for story in record["stories"]]
        for path in sorted(set(transition_paths)):
            props, body = parse_front_matter(path)
            status_tag(props, "approved")
            props["approved_at_utc"] = now
            props.pop("source_hash", None)
            props.pop("package_hash", None)
            path.write_text(front_matter(props, body), encoding="utf-8")

        refreshed, close_errors = collect(docs)
        if close_errors:
            raise ApprovalFailure("; ".join(close_errors))
        render_backlog_navigation(refreshed, docs)

        refreshed, close_errors = collect(docs)
        if close_errors:
            raise ApprovalFailure("; ".join(close_errors))
        paths = package_paths(refreshed, docs)
        for path in paths:
            props, body = parse_front_matter(path)
            props["approved_at_utc"] = now
            props.pop("source_hash", None)
            props.pop("package_hash", None)
            path.write_text(front_matter(props, body), encoding="utf-8")
        for path in paths:
            props, body = parse_front_matter(path)
            props["source_hash"] = digest(path)
            path.write_text(front_matter(props, body), encoding="utf-8")
        root_path = docs / refreshed["backlog"]["path"]
        props, body = parse_front_matter(root_path)
        props["package_hash"] = package_digest(docs, paths)
        root_path.write_text(front_matter(props, body), encoding="utf-8")

        refreshed, close_errors = collect(docs)
        close_errors.extend(approval_findings(refreshed, docs))
        if close_errors:
            raise ApprovalFailure("; ".join(sorted(set(close_errors))))
        render(refreshed, docs)
        final_record, close_errors = collect(docs)
        close_errors.extend(approval_findings(final_record, docs))
        if close_errors:
            raise ApprovalFailure("; ".join(sorted(set(close_errors))))
    except Exception as exc:
        restore_tree(docs, snapshot)
        print(json.dumps({"ok": False,
                          "errors": [f"approval rolled back: {exc}"]},
                         indent=2, ensure_ascii=False, sort_keys=True))
        return 1
    print(json.dumps({
        "ok": True, "approved_at_utc": now,
        "package_hash": final_record["backlog"]["props"]["package_hash"],
        "files": len(package_paths(final_record, docs)),
    }, indent=2, ensure_ascii=False, sort_keys=True))
    return 0


def begin_revision(args) -> int:
    """Open one incremental backlog revision without touching frozen stories.

    Delivery-aware freeze inputs are supplied by the future coordinator as a
    JSON snapshot. This offline compiler only validates the interface shape and
    records the new root/review revision; it never invents live Git state.
    """
    docs = docs_root(args.docs)
    record, errors = collect(docs)
    errors.extend(approval_findings(record, docs))
    if errors:
        print(json.dumps({"ok": False, "errors": sorted(set(errors))}, indent=2,
                         ensure_ascii=False, sort_keys=True))
        return 1
    snapshot = {}
    if args.delivery_snapshot:
        try:
            snapshot = json.loads(Path(args.delivery_snapshot).read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            print(json.dumps({"ok": False, "errors": [f"invalid delivery snapshot: {exc}"]}, indent=2), file=sys.stderr)
            return 1
        if not isinstance(snapshot, dict):
            print(json.dumps({"ok": False, "errors": ["delivery snapshot must be an object"]}, indent=2), file=sys.stderr)
            return 1
        for key in ("active_story_ids", "delivered_story_ids", "cancelled_story_ids"):
            if key in snapshot and (not isinstance(snapshot[key], list)
                                    or any(not isinstance(value, str) for value in snapshot[key])):
                print(json.dumps({"ok": False, "errors": [f"{key} must be a list of story ids"]}, indent=2), file=sys.stderr)
                return 1
    backlog_path = docs / record["backlog"]["path"]
    root_props, root_body = parse_front_matter(backlog_path)
    old_revision = int(root_props.get("revision", 0) or 0)
    revision = old_revision + 1
    status_tag(root_props, "draft")
    root_props["revision"] = revision
    for key in ("approved_at_utc", "source_hash", "package_hash"):
        root_props.pop(key, None)
    backlog_path.write_text(front_matter(root_props, root_body), encoding="utf-8")

    latest_review = latest(record["backlog_reviews"])
    next_round = int(latest_review["props"].get("round", 0) or 0) + 1
    review_props = dict(latest_review["props"])
    review_props["round"] = next_round
    review_props["status"] = "draft"
    review_props["aliases"] = [f"BACKLOG-REVIEW-{next_round:03d}"]
    for key in ("approved_at_utc", "source_hash"):
        review_props.pop(key, None)
    review_props["tags"] = [
        tag for tag in values(review_props, "tags") if not tag.startswith("status/")
    ] + ["status/draft"]
    review_path = docs / "backlog" / "reviews" / f"round-{next_round}-backlog-review.md"
    review_path.write_text(front_matter(review_props, latest_review["body"]), encoding="utf-8")
    refreshed, render_errors = collect(docs)
    if render_errors:
        print(json.dumps({"ok": False, "errors": sorted(set(render_errors))}, indent=2,
                         ensure_ascii=False, sort_keys=True))
        return 1
    render_backlog_navigation(refreshed, docs)
    print(json.dumps({
        "ok": True, "revision": revision, "review_round": next_round,
        "frozen_story_ids": sorted(set(snapshot.get("active_story_ids", []))
                                    | set(snapshot.get("delivered_story_ids", []))),
        "cancelled_story_ids": sorted(set(snapshot.get("cancelled_story_ids", []))),
        "backlog": str(backlog_path), "review": str(review_path),
    }, indent=2, ensure_ascii=False, sort_keys=True))
    return 0


def revision_status(args) -> int:
    docs = docs_root(args.docs)
    record, errors = collect(docs)
    if errors:
        print(json.dumps({"ok": False, "errors": sorted(set(errors))}, indent=2,
                         ensure_ascii=False, sort_keys=True))
        return 1
    backlog = record["backlog"]["props"]
    reviews = sorted(record["backlog_reviews"], key=lambda item: int(item["props"].get("round", 0) or 0))
    current = reviews[-1] if reviews else None
    result = {
        "ok": True,
        "revision": int(backlog.get("revision", 0) or 0),
        "backlog_status": backlog.get("status"),
        "review_round": current["props"].get("round") if current else None,
        "review_status": current["props"].get("status") if current else None,
        "approved": backlog.get("status") == "approved" and bool(backlog.get("package_hash")),
        "story_ids": sorted(item["props"].get("id") for item in record.get("stories", [])),
    }
    print(json.dumps(result, indent=2, ensure_ascii=False, sort_keys=True))
    return 0


def stub_epic(args) -> int:
    docs = docs_root(args.docs)
    if not SLUG_RE.fullmatch(args.slug):
        print("invalid epic slug", file=sys.stderr)
        return 2
    root = docs / "backlog" / "epics" / args.slug
    (root / "stories").mkdir(parents=True, exist_ok=True)
    (root / "reviews").mkdir(parents=True, exist_ok=True)
    epic_id = args.id or "EP-001"
    path = root / "epic.md"
    base_title = args.title or args.slug.replace("-", " ").title()
    backlog_title = title_of(
        docs / "backlog" / "backlog.md", designation_title(docs, "backlog")
    )
    if not path.exists():
        title = typed_title(docs, base_title, "epic")
        goal = args.goal or "Define the customer outcome and boundary."
        path.write_text(front_matter(
            {"type": "epic", "title": title, "status": "draft",
             "id": epic_id, "owner_role": "product_owner", "goal": goal,
             "tags": ["doc/epic", "status/draft"], "aliases": [epic_id]},
            f"# {title}\n\n{goal}\n"), encoding="utf-8")
    review = root / "reviews" / "round-1-epic-review.md"
    if not review.exists():
        review_title = typed_title(
            docs, f"{base_title} 1", "epic-review"
        )
        review.write_text(front_matter(
            {"type": "epic-review", "title": review_title, "status": "draft",
             "round": 1, "owner_role": "product_owner",
             "derives_from": [f"[[backlog/epics/{args.slug}/epic|{epic_id}]]"],
             "tags": ["doc/epic-review", "status/draft"],
             "aliases": [f"{epic_id}-REVIEW-001"]},
            review_body(review_title,
                        backlog_contract()["required_epic_review_sections"])),
            encoding="utf-8")
    append_nav(path, [
        "[[maps/backlog|Backlog map]]",
        f"[[backlog/backlog|{backlog_title}]]",
    ])
    append_nav(review, [
        "[[maps/backlog|Backlog map]]",
        f"[[backlog/epics/{args.slug}/epic|{epic_id}]]",
    ])
    print(root)
    return 0


def stub_story(args) -> int:
    docs = docs_root(args.docs)
    if not SLUG_RE.fullmatch(args.slug) or not SLUG_RE.fullmatch(args.epic):
        print("invalid epic or story slug", file=sys.stderr)
        return 2
    root = docs / "backlog" / "epics" / args.epic / "stories" / args.slug
    root.mkdir(parents=True, exist_ok=True)
    story_id = args.id or "ST-001"
    base_title = args.title or args.slug.replace("-", " ").title()
    story_title = typed_title(docs, base_title, "story")
    test_title = typed_title(docs, base_title, "test-plan")
    criteria = list(args.criterion_ref or [])
    experience = list(args.experience_ref or [])
    evidence = list(args.evidence_ref or [])
    design_refs = list(args.uses_design or [])
    constraint_refs = list(args.constrained_by or [])
    story = root / "story.md"
    if not story.exists():
        scope = args.scope or "Describe the smallest valuable behavior."
        epic_link = f"[[backlog/epics/{args.epic}/epic|{args.epic.upper()}]]"
        body = (
            f"# {story_title}\n\n"
            "## User Value\n\nDescribe the observable user or business value.\n\n"
            f"## Scope\n\n{scope}\n\n"
            "## Non-Goals\n\nList behavior deliberately excluded from this story.\n\n"
            "## Implementation Responsibilities\n\n"
            "- backend_developer: Own implementation and integration.\n\n"
            "## Acceptance\n\n- [ ] Map every cited criterion to an observable result.\n\n"
            "## Dependencies\n\nNone.\n\n"
            "## Delivery Notes\n\nRecord delivery constraints without execution state.\n"
        )
        story_props = {
            "type": "story", "title": story_title, "status": "planned",
            "id": story_id, "owner_role": "backend_developer",
            "supporting_roles": [], "priority": "must",
            "priority_reason": "Required for the epic outcome.", "scope": scope,
            "work_kind": args.work_kind,
            "criterion_refs": criteria, "experience_refs": experience,
            "uses_design": design_refs,
            "constrained_by": constraint_refs,
            "derives_from": [epic_link],
            "tags": ["doc/story", "status/planned"], "aliases": [story_id],
        }
        if evidence:
            story_props["related_to"] = evidence
        story.write_text(front_matter(
            story_props,
            body), encoding="utf-8")
    test = root / "test-plan.md"
    if not test.exists():
        scenario = f"{story_id}-TS-001"
        story_link = f"[[backlog/epics/{args.epic}/stories/{args.slug}/story|{story_id}]]"
        planning_sources = (criteria if args.work_kind == "feature"
                            else criteria + evidence)
        source_refs = "\n".join(f"  - {value}" for value in planning_sources)
        source_block = (f"- source_refs:\n{source_refs}\n"
                        if source_refs else "")
        test.write_text(front_matter(
            {"type": "test-plan", "title": test_title, "status": "draft",
             "revision": 1, "owner_role": "qa_engineer",
             "derives_from": [story_link], "verifies": [story_link],
             "tags": ["doc/test-plan", "status/draft"],
             "aliases": [f"{story_id}-TP"]},
            f"# {test_title}\n\n{coverage_class_table()}\n\n"
            f"## {scenario}\n\n"
            "- category: happy-path\n- target: component\n"
            "- automation: required\n"
            f"- automation_target: tests/{args.slug.replace('-', '_')}.py::test_{args.slug.replace('-', '_')}\n"
            f"{source_block}"
            "- Given: the preconditions are satisfied\n"
            "- When: the user performs the story action\n"
            "- Then: the expected outcome is observable\n"),
            encoding="utf-8")
    epic_link = f"[[backlog/epics/{args.epic}/epic|{args.epic.upper()}]]"
    story_link = (
        f"[[backlog/epics/{args.epic}/stories/{args.slug}/story|{story_id}]]"
    )
    test_link = (
        f"[[backlog/epics/{args.epic}/stories/{args.slug}/test-plan|{test_title}]]"
    )
    append_nav(story, ["[[maps/backlog|Backlog map]]", epic_link, test_link])
    append_nav(test, ["[[maps/backlog|Backlog map]]", epic_link, story_link])
    print(root)
    return 0


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    command = sub.add_parser("init")
    command.add_argument("--docs", default=None)
    command.set_defaults(func=init)
    command = sub.add_parser("stub-epic")
    command.add_argument("slug")
    command.add_argument("--docs", default=None)
    command.add_argument("--id")
    command.add_argument("--title")
    command.add_argument("--goal")
    command.set_defaults(func=stub_epic)
    command = sub.add_parser("stub-story")
    command.add_argument("epic")
    command.add_argument("slug")
    command.add_argument("--docs", default=None)
    command.add_argument("--id")
    command.add_argument("--title")
    command.add_argument("--scope")
    command.add_argument("--work-kind", choices=sorted(WORK_KINDS), default="feature")
    command.add_argument("--criterion-ref", action="append")
    command.add_argument("--experience-ref", action="append")
    command.add_argument("--evidence-ref", action="append")
    command.add_argument("--uses-design", action="append")
    command.add_argument("--constrained-by", action="append")
    command.set_defaults(func=stub_story)
    command = sub.add_parser("check")
    command.add_argument("--docs", default=None)
    command.add_argument("--approved", action="store_true")
    command.add_argument("--render", action="store_true")
    command.add_argument("--json", action="store_true")
    command.set_defaults(func=check)
    command = sub.add_parser("status")
    command.add_argument("--docs", default=None)
    command.add_argument("--json", action="store_true")
    command.set_defaults(func=lambda args: check(argparse.Namespace(
        docs=args.docs, approved=False, render=False, json=args.json)))
    command = sub.add_parser("approve")
    command.add_argument("--docs", default=None)
    command.set_defaults(func=approve)
    command = sub.add_parser("begin-revision")
    command.add_argument("--docs", default=None)
    command.add_argument("--delivery-snapshot")
    command.set_defaults(func=begin_revision)
    command = sub.add_parser("revision-status")
    command.add_argument("--docs", default=None)
    command.set_defaults(func=revision_status)
    args = parser.parse_args(argv)
    return args.func(args)


if __name__ == "__main__":
    raise SystemExit(main())
